<?php $pageTitle='Dashboard';require_once dirname(__DIR__).'/includes/header.php';require_once dirname(__DIR__).'/includes/auth.php';require_auth();require dirname(__DIR__).'/includes/sidebar.php';$t=active_tournament($pdo);$tid=(int)($t['id']??0);$stats=tournament_stats($pdo,$tid);$pc=$pdo->prepare('SELECT COUNT(*) FROM participants WHERE tournament_id=?');$pc->execute([$tid]);$participants=(int)$pc->fetchColumn();$recent=$pdo->prepare("SELECT m.*,p1.name p1_name,p2.name p2_name FROM matches m LEFT JOIN participants p1 ON p1.id=m.participant1_id LEFT JOIN participants p2 ON p2.id=m.participant2_id WHERE m.tournament_id=? ORDER BY m.updated_at DESC LIMIT 8");$recent->execute([$tid]);$audits=$pdo->query("SELECT a.*,u.name user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 8")->fetchAll();$progress=$stats['total']?(int)round($stats['finished']/$stats['total']*100):0;?>
<div class="grid grid-4"><div class="card stat-card"><span class="stat-icon"><i class="fa-solid fa-users"></i></span><strong><?=$participants?></strong><small>Total Participants</small></div><div class="card stat-card"><span class="stat-icon"><i class="fa-solid fa-gamepad"></i></span><strong><?=$stats['total']?></strong><small>Total Matches</small></div><div class="card stat-card"><span class="stat-icon"><i class="fa-solid fa-circle-check"></i></span><strong><?=$stats['finished']?></strong><small>Matches Finished</small></div><div class="card stat-card"><span class="stat-icon"><i class="fa-solid fa-bolt"></i></span><strong><?=$stats['live']?></strong><small>Matches Live</small></div></div>
<div class="grid grid-3" style="margin-top:20px"><div class="card progress-card"><div class="eyebrow">Tournament progress</div><div class="progress-row"><strong><?=$progress?>%</strong><span><?=$stats['finished']?> / <?=$stats['total']?> matches</span></div><div class="progress-track"><div class="progress-fill" style="width:<?=$progress?>%"></div></div><p style="color:var(--text-secondary)"><?=e($t['name']??'No active tournament')?></p></div><div class="card" style="grid-column:span 2"><div class="section-head"><div><div class="eyebrow">Operations</div><h2>Recent matches</h2></div><a class="btn btn-sm" href="matches.php">Manage</a></div><div class="table-wrap"><table><thead><tr><th>Match</th><th>Round</th><th>Score</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($recent->fetchAll() as $m):?><tr><td><?=e($m['p1_name']??'TBD')?> vs <?=e($m['p2_name']??'TBD')?></td><td><?=e($m['round'])?></td><td><strong><?=$m['score1']?> : <?=$m['score2']?></strong></td><td><span class="badge <?=e($m['status'])?>"><?=e($m['status'])?></span></td><td><a class="btn btn-sm" href="scoring.php?match_id=<?=$m['id']?>">Score</a></td></tr><?php endforeach;?></tbody></table></div></div></div>
<section class="card" style="margin-top:20px"><div class="section-head"><div><div class="eyebrow">Traceability</div><h2>Audit log</h2></div></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Description</th></tr></thead><tbody><?php foreach($audits as $a):?><tr><td><?=date('d M H:i:s',strtotime($a['created_at']))?></td><td><?=e($a['user_name']??'System')?></td><td><span class="badge"><?=e($a['action'])?></span></td><td><?=e($a['description'])?></td></tr><?php endforeach;?></tbody></table></div></section>
